using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
public static class ValidateProgressiveForestRwd{
 public static object Main(){
 if(!Application.isPlaying)throw new Exception("Requires Play Mode");
 var source=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>();var sourceBody=source.GetComponent<Rigidbody>();var mode=Physics.simulationMode;bool paused=EditorApplication.isPaused,kinematic=sourceBody.isKinematic;var velocity=sourceBody.linearVelocity;var angular=sourceBody.angularVelocity;GameObject clone=null,probe=null;
 try{EditorApplication.isPaused=true;Physics.simulationMode=SimulationMode.Script;sourceBody.isKinematic=true;
 clone=UnityEngine.Object.Instantiate(source.gameObject,new Vector3(35,.65f,-25),Quaternion.identity);var car=clone.GetComponent<VehiclePhysics>();car.automaticSimulation=false;car.externalControl=true;clone.GetComponent<VehiclePlayerInput>().enabled=false;var audio=clone.GetComponent<VehicleAudio>();if(audio!=null)audio.enabled=false;var body=clone.GetComponent<Rigidbody>();body.isKinematic=false;car.Initialize();car.SetNeutral(false);car.SetFourWheelDrive(false);car.SetTransmission(false,false);car.SetInput(new VehicleControlInput{brake=1});Physics.SyncTransforms();
 Action step=()=>{car.Simulate(.01f);Physics.Simulate(.01f);SoftGroundRuts.AdvanceAll(.01f);};for(int i=0;i<150;i++)step();var start=body.position;float peakSlip=0;int groundedBefore=car.Wheels.Count(w=>w.isGrounded);car.SetInput(new VehicleControlInput{throttle=.8f});int stamped=0;float peak=0;
 for(int i=0;i<600;i++){float z=body.position.z+4;float s=Mathf.Sin(z*Mathf.PI/50);float target=12*s*s*s;float angle=Vector3.SignedAngle(clone.transform.forward,new Vector3(target-body.position.x,0,4),Vector3.up);car.SetInput(new VehicleControlInput{throttle=.8f,steering=0});step();peak=Mathf.Max(peak,car.SpeedKmh);peakSlip=Mathf.Max(peakSlip,car.WheelspinSpeed);foreach(var wheel in car.Wheels)if(wheel.GetGroundHit(out var hit)){var tracks=hit.collider.GetComponent<TireTrackRenderer>();if(tracks!=null&&tracks.TrackAt(hit.point)>0)stamped++;}}
 car.SetInput(new VehicleControlInput{brake=1});for(int i=0;i<200;i++)step();
 float firstTravel=Vector3.Distance(start,body.position);var restart=body.position;for(int i=0;i<300;i++){car.SetInput(new VehicleControlInput{throttle=.8f});step();}float restartTravel=Vector3.Distance(restart,body.position);car.SetInput(new VehicleControlInput{brake=1});for(int i=0;i<150;i++)step();int groundedAfter=car.Wheels.Count(w=>w.isGrounded);var soils=GameObject.Find("Soft forest floor - wheel ruts").GetComponentsInChildren<SoftGroundRuts>();foreach(var soil in soils)soil.Commit();float depth=soils.Max(s=>s.DugDepth);float travel=Vector3.Distance(start,body.position);int checks=0;float mismatch=0;foreach(var soil in soils.Where(s=>s.DugDepth>.0001f)){
 probe=new GameObject("Independent visible rut probe");probe.transform.position=soil.transform.position;var collider=probe.AddComponent<MeshCollider>();collider.sharedMesh=soil.GetComponent<MeshFilter>().sharedMesh;var verts=collider.sharedMesh.vertices;foreach(var p in verts.Where(p=>p.y<-.001f).Take(30)){var ray=new Ray(soil.transform.TransformPoint(p)+Vector3.up,Vector3.down);if(!collider.Raycast(ray,out var visible,2)||!soil.GetComponent<MeshCollider>().Raycast(ray,out var physical,2))throw new Exception("Rut ray missed");mismatch=Mathf.Max(mismatch,Mathf.Abs(visible.point.y-physical.point.y));if(GameObject.Find("Ground - square 100 x 100 m").GetComponent<MeshCollider>().enabled&&GameObject.Find("Ground - square 100 x 100 m").GetComponent<MeshCollider>().Raycast(ray,out var under,2))throw new Exception("Invisible gravel under road");checks++;}UnityEngine.Object.DestroyImmediate(probe);probe=null;}
 if(restartTravel<.2f||groundedAfter!=car.Wheels.Length||groundedBefore!=car.Wheels.Length||travel<1||depth<.04f||depth>.111f||peak>18||stamped<20||checks==0||mismatch>.002f)throw new Exception("Drive failed travel="+travel+" depth="+depth+" stamped="+stamped+" grounded="+groundedBefore+" final="+groundedAfter+" restart="+restartTravel);
 return new{success=true,throttleSeconds=6,restartSeconds=3,travel,firstTravel,restartTravel,peakKmh=peak,peakSlipMetresPerSecond=peakSlip,finalBodyHeight=body.position.y,maximumDepth=depth,finalGrounded=groundedAfter,treadContactSamples=stamped,groundedBefore,visibleCollisionChecks=checks,maxMismatch=mismatch};
 }finally{if(clone!=null)UnityEngine.Object.DestroyImmediate(clone);if(probe!=null)UnityEngine.Object.DestroyImmediate(probe);sourceBody.isKinematic=kinematic;if(!kinematic){sourceBody.linearVelocity=velocity;sourceBody.angularVelocity=angular;}Physics.simulationMode=mode;EditorApplication.isPaused=paused;}
 }
}


